def quote(amount: int, tax_rate: float) -> float:
    return amount * (1 + tax_rate)
print(quote(100, 0.05))

class MemoryStore:
    def __init__(self): self.values = []
    def save(self, value): self.values.append(value)
def register(store, name): store.save(name.strip())
store = MemoryStore(); register(store, ' Asha ')
print(store.values)

def build_service(use_memory: bool):
    return 'memory' if use_memory else 'sqlite'
print(build_service(True), build_service(False))
